+            // for each option.
+            for (final Iterator i = list.iterator(); i.hasNext();) {
+                final Option option = (Option) i.next();

+                // append usage information
+                option.appendUsage(buffer, childSettings, comp);

+                // add separators as needed
+                if (i.hasNext()) {
