86   public boolean hasEqualParameters(ArrowType that) {
87     if (parameters.getChildCount() != that.parameters.getChildCount()) {
88       return false;
89     }
90     for (Node param1 : parameters.children()) {
91       Node param2 = that.parameters.getChildAtIndex(
